import{_ as a,a as e,o as i,a6 as s}from"./chunks/framework.CJDy2q7X.js";const u=JSON.parse('{"title":"Authentication (REST)","description":"","frontmatter":{"outline":false},"headers":[],"relativePath":"api/rest-api/authentication.md","filePath":"api/rest-api/authentication.md","lastUpdated":1787725411000}'),o={name:"api/rest-api/authentication.md"};function n(r,t,h,l,c,d){return i(),e("div",null,t[0]||(t[0]=[s(`<h1 id="authentication-rest" tabindex="-1">Authentication (REST) <a class="header-anchor" href="#authentication-rest" aria-label="Permalink to &quot;Authentication (REST)&quot;">​</a></h1><p>The full authentication model — public access, customer login, guest checkout, and admin — lives on the central <a href="/api/authentication.html">Authentication</a> page. This page is the <strong>REST-specific</strong> quickref: the base URLs, the headers, and the exact calls.</p><h2 id="base-urls" tabindex="-1">Base URLs <a class="header-anchor" href="#base-urls" aria-label="Permalink to &quot;Base URLs&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Surface</th><th>Base</th><th>Headers</th></tr></thead><tbody><tr><td>Shop</td><td><code>/api/shop/*</code></td><td><code>X-STOREFRONT-KEY</code> (always) + <code>Authorization: Bearer &lt;token&gt;</code> for customer actions</td></tr><tr><td>Admin</td><td><code>/api/admin/*</code></td><td><code>Authorization: Bearer &lt;id&gt;|&lt;token&gt;</code> only (no storefront key)</td></tr></tbody></table><h2 id="public-access" tabindex="-1">Public access <a class="header-anchor" href="#public-access" aria-label="Permalink to &quot;Public access&quot;">​</a></h2><p>The <code>X-STOREFRONT-KEY</code> alone gives read-only access to public data (products, categories, CMS):</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">curl</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -X</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> GET</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;https://your-domain.com/api/shop/products&quot;</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  -H</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;X-STOREFRONT-KEY: pk_storefront_xxxxxxxxxxxxx&quot;</span></span></code></pre></div><h2 id="customer-login-—-get-a-token" tabindex="-1">Customer login — get a token <a class="header-anchor" href="#customer-login-—-get-a-token" aria-label="Permalink to &quot;Customer login — get a token&quot;">​</a></h2><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">curl</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -X</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> POST</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;https://your-domain.com/api/shop/customer/login&quot;</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  -H</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;Content-Type: application/json&quot;</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  -H</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;X-STOREFRONT-KEY: pk_storefront_xxxxxxxxxxxxx&quot;</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  -d</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &#39;{&quot;email&quot;:&quot;john@example.com&quot;,&quot;password&quot;:&quot;SecurePass@123&quot;}&#39;</span></span></code></pre></div><p>The response returns <code>token</code> (format <code>&lt;id&gt;|&lt;secret&gt;</code>) — send it as <code>Authorization: Bearer &lt;token&gt;</code> on every authenticated request. Use <code>token</code>, <strong>not</strong> <code>apiToken</code> (a legacy field that is not a Bearer). There is no refresh token — on a <code>401</code>, log in again. Full field reference on the <a href="/api/rest-api/shop/customers/customer-login.html">Customer Login</a> page.</p><h2 id="guest-—-act-without-login" tabindex="-1">Guest — act without login <a class="header-anchor" href="#guest-—-act-without-login" aria-label="Permalink to &quot;Guest — act without login&quot;">​</a></h2><p>A guest can build a cart and place an order using a <strong>cart token</strong> as the Bearer: create a cart to obtain the token — <a href="/api/rest-api/shop/cart/create-cart.html">Create Cart</a> — then send it as <code>Authorization: Bearer &lt;cartToken&gt;</code> alongside the <code>X-STOREFRONT-KEY</code> on cart and checkout calls. See the <a href="/api/workflows/shop/cart.html">Cart</a> and <a href="/api/workflows/shop/checkout.html">Checkout</a> workflows.</p><h2 id="admin" tabindex="-1">Admin <a class="header-anchor" href="#admin" aria-label="Permalink to &quot;Admin&quot;">​</a></h2><p>Admin clients use a pre-issued <strong>Integration token</strong> (no login) sent as <code>Authorization: Bearer &lt;id&gt;|&lt;token&gt;</code> to <code>/api/admin/*</code>. See <a href="/api/rest-api/admin/authentication.html">Admin Authentication</a> for the token model, permissions, IP allowlist, expiry, and rate limits.</p><h2 id="related" tabindex="-1">Related <a class="header-anchor" href="#related" aria-label="Permalink to &quot;Related&quot;">​</a></h2><ul><li><a href="/api/authentication.html">Authentication</a> — the full model (public / customer / guest / admin)</li><li><a href="/api/errors.html">Status Codes</a> — how failures are reported (including <code>401</code>)</li><li><a href="/api/pagination.html">Pagination</a> · <a href="/api/sorting.html">Sorting</a></li></ul>`,16)]))}const k=a(o,[["render",n]]);export{u as __pageData,k as default};
